import { expect, test, type Page } from "@playwright/test";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

// End-to-end translator flows against the real UI. Prerequisites (see
// e2e/README.md): backend running with the corpus imported, Tesseract
// provisioned, and the fixture PNGs generated by
// training/ocr/generate_fixtures.py. Each spec skips with the missing
// prerequisite named when its fixture image is absent; when the
// fixture exists but OCR is not provisioned, the spec skips after the
// backend's honest error appears — these specs never fabricate an
// expected translation: expected English is read from the committed
// corpus fixture file.

const FIXTURES = path.resolve(__dirname, "../../training/ocr/fixtures");
const SAMPLE = path.resolve(__dirname, "../../training/datasets/fixtures/sample_passages.jsonl");

function fixtureImage(name: string): string {
  const p = path.join(FIXTURES, name);
  test.skip(!existsSync(p),
    `prerequisite missing: ${p} — generate it with training/ocr/generate_fixtures.py`);
  return p;
}

function passage(reference: string) {
  const rows = readFileSync(SAMPLE, "utf-8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
  const found = rows.find((p) => p.reference === reference);
  if (!found) throw new Error(`fixture passage ${reference} missing from sample_passages.jsonl`);
  return found;
}

async function uploadAndOcr(page: Page, image: string) {
  await page.goto("/");
  await page.locator("#file-input").setInputFiles(image);
  await expect(page.getByTestId("upload-preview")).toBeVisible();
  await expect(page.getByTestId("ocr-run")).toBeEnabled(); // backend stored the upload
  await page.getByTestId("ocr-run").click();
  // OCR finishes either with captured text in the raw region or with
  // the backend's explicit error in the alert region.
  await expect.poll(async () => {
    const raw = await page.getByTestId("raw-ocr").textContent();
    const alerted = (await page.getByRole("alert").count()) > 0;
    return raw && !raw.includes("No OCR output yet") ? "text" : alerted ? "error" : "pending";
  }, { timeout: 30_000 }).not.toBe("pending");
  const raw = await page.getByTestId("raw-ocr").textContent();
  if (!raw || raw.includes("No OCR output yet")) {
    test.skip(true, "prerequisite missing: OCR produced no text — provision " +
      "Tesseract (binary + Hebrew traineddata) per docs/OCR.md");
  }
}

test("Hebrew flow: upload, OCR, verified translation, copy, export", async ({ page }) => {
  const image = fixtureImage("genesis-1-1.png");
  await uploadAndOcr(page, image);

  // The corrected editor is prefilled from the captured text.
  await expect(page.getByTestId("corrected-source")).not.toHaveValue("");

  await page.getByTestId("translate-run").click();
  const output = page.getByTestId("translation-output");
  // The fixture page is Genesis 1:1, a verified corpus passage: the
  // English shown must be the corpus reference translation.
  const gen = passage("Genesis 1:1");
  await expect(output).toContainText(gen.english_text.slice(0, 40), { timeout: 30_000 });

  await page.getByTestId("copy-english").click();
  const clipboard = await page.evaluate(() => navigator.clipboard.readText());
  expect(clipboard).toContain(gen.english_text.slice(0, 40));

  const downloadPromise = page.waitForEvent("download");
  await page.getByTestId("export-json").click();
  const download = await downloadPromise;
  expect(download.suggestedFilename()).toBe("ahaiet-result.json");
});

test("Aramaic flow: explicit Aramaic profile, verified translation", async ({ page }) => {
  const image = fixtureImage("daniel-2-4.png");
  await page.goto("/");
  // Select the Aramaic profile explicitly: script alone never decides.
  await page.getByLabel(/Language profile/).selectOption("biblical_aramaic");
  await page.locator("#file-input").setInputFiles(image);
  await expect(page.getByTestId("upload-preview")).toBeVisible();
  await expect(page.getByTestId("ocr-run")).toBeEnabled();
  await page.getByTestId("ocr-run").click();
  await expect.poll(async () => {
    const raw = await page.getByTestId("raw-ocr").textContent();
    const alerted = (await page.getByRole("alert").count()) > 0;
    return raw && !raw.includes("No OCR output yet") ? "text" : alerted ? "error" : "pending";
  }, { timeout: 30_000 }).not.toBe("pending");
  const raw = await page.getByTestId("raw-ocr").textContent();
  if (!raw || raw.includes("No OCR output yet")) {
    test.skip(true, "prerequisite missing: OCR produced no text — provision " +
      "Tesseract (binary + Hebrew traineddata) per docs/OCR.md");
  }

  await page.getByTestId("translate-run").click();
  // Daniel 2:4 is a verified Aramaic corpus passage: either its
  // verified translation appears, or the backend's explicit error
  // state does — never a result produced under the Hebrew profile.
  const output = page.getByTestId("translation-output");
  const alert = page.getByRole("alert");
  await expect(output.or(alert).first()).toBeVisible({ timeout: 30_000 });
  if (await alert.count()) {
    await expect(alert).not.toContainText("biblical_hebrew");
  } else {
    const dan = passage("Daniel 2:4");
    await expect(output).toContainText(dan.english_text.slice(0, 40));
  }
});
